from app.db import store


def get_user(user_id: int) -> dict | None:
    return store.get_by_id(user_id)


def search_users(terms: list[str]) -> list[dict]:
    """Return users whose name contains every term as a case-insensitive substring, ordered by id."""
    lowered = [term.lower() for term in terms]
    return [
        user
        for user in store.find_all()
        if all(term in user["name"].lower() for term in lowered)
    ]
